import { useState, useEffect } from 'react';
import { Cookie } from 'lucide-react';
import type { Language } from '@/lib/i18n';
import { 
  hasConsentPreferences, 
  saveConsentPreferences, 
  createAcceptAllConsent, 
  createRejectAllConsent 
} from '@/lib/consent';

interface CookieConsentProps {
  language: Language;
  onOpenManager?: () => void;
}

export function CookieConsent({ language, onOpenManager }: CookieConsentProps) {
  const [isVisible, setIsVisible] = useState(false);
  const [isAnimatingOut, setIsAnimatingOut] = useState(false);

  useEffect(() => {
    if (!hasConsentPreferences()) {
      setTimeout(() => setIsVisible(true), 1000);
    }
  }, []);

  const handleAcceptAll = async () => {
    await saveConsentPreferences(createAcceptAllConsent());
    setIsAnimatingOut(true);
    setTimeout(() => setIsVisible(false), 400);
  };

  const handleRejectAll = async () => {
    await saveConsentPreferences(createRejectAllConsent());
    setIsAnimatingOut(true);
    setTimeout(() => setIsVisible(false), 400);
  };

  const handleManagePreferences = () => {
    // Immediately call onOpenManager so modal can render
    onOpenManager?.();
    // Then animate banner out
    setIsAnimatingOut(true);
    setTimeout(() => {
      setIsVisible(false);
    }, 400);
  };

  if (!isVisible) return null;

  const text = {
    en: {
      message: 'We use cookies to improve your experience, secure your account, and personalize offers.',
      policy: 'By continuing, you agree to our',
      privacyPolicy: 'Privacy Policy',
      acceptAll: 'Accept All',
      rejectAll: 'Reject All',
      manage: 'Manage Preferences',
    },
    he: {
      message: 'אנו משתמשים בעוגיות לשיפור החוויה, אבטחת החשבון והתאמת מבצעים אישיים.',
      policy: 'בשימוש באתר אתה מסכים ל',
      privacyPolicy: 'מדיניות הפרטיות',
      acceptAll: 'אישור הכל',
      rejectAll: 'דחיית הכל',
      manage: 'התאמה אישית',
    },
    ar: {
      message: 'نستخدم ملفات تعريف الارتباط لتحسين تجربتك وتأمين حسابك وتخصيص العروض.',
      policy: 'بالمتابعة، فإنك توافق على',
      privacyPolicy: 'سياسة الخصوصية',
      acceptAll: 'قبول الكل',
      rejectAll: 'رفض الكل',
      manage: 'إدارة التفضيلات',
    },
    ru: {
      message: 'Мы используем файлы cookie для улучшения вашего опыта, защиты учетной записи и персонализации предложений.',
      policy: 'Продолжая, вы соглашаетесь с нашей',
      privacyPolicy: 'Политикой конфиденциальности',
      acceptAll: 'Принять все',
      rejectAll: 'Отклонить все',
      manage: 'Настроить',
    },
    fr: {
      message: 'Nous utilisons des cookies pour améliorer votre expérience, sécuriser votre compte et personnaliser les offres.',
      policy: 'En continuant, vous acceptez notre',
      privacyPolicy: 'Politique de confidentialité',
      acceptAll: 'Tout accepter',
      rejectAll: 'Tout refuser',
      manage: 'Gérer les préférences',
    },
    es: {
      message: 'Utilizamos cookies para mejorar su experiencia, proteger su cuenta y personalizar las ofertas.',
      policy: 'Al continuar, acepta nuestra',
      privacyPolicy: 'Política de privacidad',
      acceptAll: 'Aceptar todo',
      rejectAll: 'Rechazar todo',
      manage: 'Gestionar preferencias',
    },
  };

  const t = text[language];

  // RTL languages: Hebrew and Arabic
  const isRTL = language === 'he' || language === 'ar';
  
  return (
    <div 
      data-testid="cookie-consent-banner"
      className={`fixed bottom-20 left-1/2 -translate-x-1/2 w-[calc(100%-2rem)] sm:w-auto sm:max-w-md z-40 transition-all duration-400 ${
        isAnimatingOut ? 'opacity-0 translate-y-4 scale-95' : 'opacity-100 translate-y-0 scale-100'
      }`}
      style={{
        animation: isAnimatingOut ? 'none' : 'slideInUp 0.5s cubic-bezier(0.16, 1, 0.3, 1)',
      }}
    >
      <div 
        className="backdrop-blur-xl rounded-2xl p-5 shadow-2xl"
        style={{
          background: '#FFFFFF',
          border: '1px solid #000000',
          boxShadow: '0 20px 60px rgba(0, 0, 0, 0.15)',
        }}
      >
        <div className="flex gap-4">
          <div 
            className="flex-shrink-0 w-10 h-10 rounded-full flex items-center justify-center"
            style={{
              background: '#000000',
            }}
          >
            <Cookie className="w-5 h-5 text-white" />
          </div>
          
          <div className="flex-1 min-w-0">
            <p 
              className="text-sm text-gray-700 mb-3 leading-relaxed"
              style={{
                fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
                fontWeight: 300,
              }}
            >
              {t.message}
            </p>
            
            <p 
              className="text-xs text-gray-500 mb-4"
              style={{
                fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
                fontWeight: 300,
              }}
            >
              {t.policy}{' '}
              <a 
                href="/privacy-policy" 
                className="inline-flex items-center hover:opacity-80 transition-opacity"
                style={{
                  color: '#000000',
                  fontWeight: 500,
                  textDecoration: 'underline',
                }}
              >
                {t.privacyPolicy}
              </a>
            </p>
            
            <div className="flex flex-col gap-2">
              <button
                onClick={handleAcceptAll}
                className="btn-gucci-black w-full hover:opacity-90 transition-all duration-200 px-4 py-2.5 text-sm rounded-xl shadow-lg"
                style={{
                  fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
                  fontWeight: 500,
                }}
                data-testid="button-accept-all-cookies"
              >
                {t.acceptAll}
              </button>
              
              <div className="flex gap-2">
                <button
                  onClick={handleRejectAll}
                  className="flex-1 bg-white hover:bg-gray-100 text-black border border-black transition-all duration-200 px-4 py-2.5 text-sm rounded-xl"
                  style={{
                    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
                    fontWeight: 400,
                  }}
                  data-testid="button-reject-all-cookies"
                >
                  {t.rejectAll}
                </button>
                
                <button
                  onClick={handleManagePreferences}
                  className="flex-1 bg-white hover:bg-gray-100 text-black border border-black transition-all duration-200 px-4 py-2.5 text-sm rounded-xl"
                  style={{
                    fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
                    fontWeight: 400,
                  }}
                  data-testid="button-manage-cookies"
                >
                  {t.manage}
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
      
      <style>{`
        @keyframes slideInUp {
          from {
            opacity: 0;
            transform: translateY(20px) scale(0.95);
          }
          to {
            opacity: 1;
            transform: translateY(0) scale(1);
          }
        }
      `}</style>
    </div>
  );
}
